              "canon-technologiestack-flutter-dart"
            ]
          },
          {
            "itemId": "ARCH-38",
            "text": "Das Paket GetX soll als technische Option berücksichtigt und in der Umsetzung erprobt werden.",
            "sourceClaimIds": [
              "canon-getx-pruefen"
            ]
          },
          {
            "itemId": "ARCH-39",
            "text": "Als Datenbank der Pflege-App wird Google Firestore verwendet.",
            "sourceClaimIds": [
              "no-go-global-statt-pro-bewohner"
            ]
          },
          {
            "itemId": "ARCH-40",
            "text": "Es muss geklärt werden, ob und wie Cloud-Daten lokal auf dem Gerät gespeichert oder gecacht werden sollen. [canon-lokaler-cache-klären]",
            "sourceClaimIds": []
          },
          {
            "itemId": "ARCH-41",
            "text": "Es soll evaluiert werden, ob die App zusätzlich auf Tablets nutzbar sein kann.",
            "sourceClaimIds": [
              "canon-tablet-support-pruefen"
            ]
          },
          {
            "itemId": "ARCH-42",
            "text": "Wenn im About-Me-Bereich neue Inhalte hochgeladen werden, sollen verbundene Nutzer derselben Einrichtung per Popup benachrichtigt werden.",
            "sourceClaimIds": [
              "canon-benachrichtigungen-about-me-updates"
            ]
          },
          {
            "itemId": "ARCH-43",
            "text": "Die genauen Bedürfnisse und Funktionen des Systems müssen durch Anforderungsanalyse mit mehreren Beteiligten und künftigen Nutzern erarbeitet werden.",
