              "canon-anforderungsanalyse-mit-nutzern",
              "ADJ-GAP-AU-0002"
            ]
          },
          {
            "itemId": "ARCH-44",
            "text": "Zur Nutzerforschung sollen Vor-Ort-Termine in Einrichtungen durchgeführt werden, um reale Kommunikationssituationen und Bedürfnisse besser zu verstehen.",
            "sourceClaimIds": [
              "canon-beobachtung-vor-ort"
            ]
          },
